const nav = code.match(/<nav[\s\S]*?<\/nav>/i);
if (!nav || !/<a\s+[\s\S]*href=/i.test(nav[0])) {
  throw new Error("Put your menu inside <nav> … </nav>.");
}

const nav = code.match(/<nav[\s\S]*?<\/nav>/i)[0];
if (!/<ul[\s\S]*<\/ul>/i.test(nav)) {
  throw new Error("A menu is a list of links — use <ul> around the <li> items.");
}

const nav = code.match(/<nav[\s\S]*?<\/nav>/i)[0];
const ul = nav.match(/<ul[\s\S]*?<\/ul>/i)[0];
const items = (ul.match(/<li[\s\S]*?<\/li>/gi) ?? []).length;
if (items !== 3) throw new Error(`Expected 3 <li> items, found ${items}.`);
for (const target of ["#about", "#projects", "#contact"]) {
  if (!nav.includes(`href="${target}"`)) {
    throw new Error(`Missing a link to ${target}.`);
  }
}

const nav = code.match(/<nav[\s\S]*?<\/nav>/i)[0];
const links = [...nav.matchAll(/<a\s[^>]*href=["'][^"']*["'][^>]*>([\s\S]*?)<\/a>/gi)];
if (links.length < 3 || links.some((l) => l[1].trim().length === 0)) {
  throw new Error("Every <a> needs visible text between the tags — empty links are unusable.");
}
